% %Answers question of if drone battery can withstand a flight at different
% %SOC
% %This script runs this at every SOC and shows where the limit of the
% %battery is
% %The aim is to identify a limit of the battery
% %Records if the quad lands or hits cutoff
% 
% % AI-USE ATTRIBUTION (MEC4128Z plagiarism declaration, item 4)
% %   The initial draft of this script was generated by Claude (Anthropic),
% %   on 13 October 2026, from a prompt written by Haaniya Carelse, CRLHAA001
% %   It was subsequently reviewed, tested and modified
mdl      = 'Quadcopter_2DoF_Model_7_a';   % model with the failsafe
V_cut    = 9.0;                           % hard cutoff (V)
coarse   = 1.0 : -0.1 : 0.3;              % starting SOCs for the first sweep
fineStep = 0.01;                          % resolution of the refinement

load_system(mdl);

results = runSweep(mdl, coarse, V_cut); % run model for each of the 8 SOCs

iLast = find(results.Outcome == "Completed", 1, 'last');
if ~isempty(iLast) && iLast < height(results)
    hiSOC = results.SOC0(iLast);
    loSOC = results.SOC0(iLast + 1);
    fine  = round((hiSOC - fineStep) : -fineStep : (loSOC + fineStep), 2);
    if ~isempty(fine)
        results = [results; runSweep(mdl, fine, V_cut)];
        results = sortrows(results, 'SOC0', 'descend');
    end
end

clear soc0   % next normal Run goes back to the InitFcn default (1.0)

disp(results(:, 1:end-2))   % hide the time/voltage traces

minDone = min(results.SOC0(results.Outcome == "Completed"));
minSafe = min(results.SOC0(results.Outcome ~= "Crash"));
if isempty(minDone)
    fprintf('\nNo starting SOC completed the mission.\n');
else
    fprintf('\nMinimum starting SOC to complete the mission: %.2f\n', minDone);
end
if ~isempty(minSafe)
    fprintf('Lowest starting SOC tested that still landed safely: %.2f\n', minSafe);
end

save('soc_sweep_results.mat', 'results');
writetable(results(:, 1:end-2), 'soc_sweep_results.csv');

figure('Name', 'SOC sweep'); hold on; grid on
for k = 1:height(results)
    plot(results.t{k}, results.V{k}, 'DisplayName', ...
        sprintf('SOC_0 = %.2f (%s)', results.SOC0(k), results.Outcome(k)));
end
yline(V_cut, 'k--', 'Cutoff', 'HandleVisibility', 'off');
yline(9.6, 'k:', 'Failsafe', 'HandleVisibility', 'off');
xlabel('Time (s)'); ylabel('Terminal voltage U_L (V)');
legend('Location', 'eastoutside');

function T = runSweep(mdl, socList, V_cut)

Q = 0.55;
n = numel(socList);

SOC0 = socList(:);
tEnd = nan(n,1);
tTrig = nan(n,1);
Vmin = nan(n,1); 
zEnd = nan(n,1);
SOCend = nan(n,1); 
Energy_Wh = nan(n,1);
Outcome = strings(n,1);
t = cell(n,1); 
V = cell(n,1);

for k = 1:n
    assignin('base', 'soc0', socList(k));    % InitFcn keeps this value
    fprintf('Running SOC0 = %.2f ...\n', socList(k));
    out = sim(mdl, 'ReturnWorkspaceOutputs', 'on');

    [tv, Vk] = getSig(out, 'V_log');
    [~,  zk] = getSig(out, 'z_log');
    [te, ek] = getSig(out, 'emg_flag');

    tEnd(k) = tv(end);
    Vmin(k) = min(Vk);
    zEnd(k) = zk(end);
    iT = find(ek > 0.5, 1);
    if ~isempty(iT), tTrig(k) = te(iT); end

    [ti, Ik] = getSig(out, 'I_log');          % optional
    if ~isempty(Ik), SOCend(k) = socList(k) - trapz(ti, Ik)/(3600*Q); end
    [~, Ek] = getSig(out, 'E_log');           % optional
    if ~isempty(Ek), Energy_Wh(k) = Ek(end); end

    landed = zEnd(k) <= 0.05 && Vmin(k) > V_cut + 1e-3;
    if ~landed
        Outcome(k) = "Crash";
    elseif isnan(tTrig(k))
        Outcome(k) = "Completed";
    else
        Outcome(k) = "Emergency";
    end

    t{k} = tv;  V{k} = Vk;
end

T = table(SOC0, Outcome, tTrig, tEnd, Vmin, zEnd, SOCend, Energy_Wh, t, V);
end

function [tt, yy] = getSig(out, name)
% Reads a logged timeseries; returns empty if the signal was not logged.
tt = []; yy = [];
if ~any(strcmp(out.who, name)), return; end
s = out.get(name);
if isa(s, 'timeseries')
    tt = s.Time;  yy = squeeze(s.Data);
elseif isstruct(s)
    tt = s.time;  yy = s.signals.values;
else
    tt = out.tout; yy = s;
end
tt = tt(:); yy = yy(:);
end

